import json, base64, math, zlib, re
from pathlib import Path
from collections import Counter

# grab few samples of varied size
samples = []
for f in (Path.home()/".claude"/"projects").rglob("*.jsonl"):
    for line in open(f, errors="replace"):
        if '"thinking"' not in line: continue
        try: rec = json.loads(line)
        except: continue
        for b in ((rec.get("message") or {}).get("content") or []):
            if isinstance(b, dict) and b.get("type")=="thinking" and b.get("signature"):
                samples.append(base64.b64decode(b["signature"]+"==="))
    if len(samples) > 300: break

samples.sort(key=len)
picks = [samples[0], samples[len(samples)//2], samples[-1]]

def parse_proto(buf, depth=0, maxd=3):
    """minimal protobuf wire parser"""
    out = []
    i = 0
    while i < len(buf):
        try:
            # varint key
            key = 0; shift = 0
            while True:
                byte = buf[i]; i += 1
                key |= (byte & 0x7f) << shift; shift += 7
                if not byte & 0x80: break
            field, wt = key >> 3, key & 7
            if wt == 0:
                v = 0; shift = 0
                while True:
                    byte = buf[i]; i += 1
                    v |= (byte & 0x7f) << shift; shift += 7
                    if not byte & 0x80: break
                out.append((field, 'varint', v))
            elif wt == 2:
                ln = 0; shift = 0
                while True:
                    byte = buf[i]; i += 1
                    ln |= (byte & 0x7f) << shift; shift += 7
                    if not byte & 0x80: break
                data = buf[i:i+ln]; i += ln
                out.append((field, 'bytes', data))
            else:
                return None  # unsupported wire type -> probably not proto
        except IndexError:
            return None
    return out

def entropy(b):
    if not b: return 0
    c = Counter(b)
    return -sum(n/len(b)*math.log2(n/len(b)) for n in c.values())

for s in picks:
    print(f"\n=== blob {len(s)} bytes, entropy {entropy(s):.2f} bits/byte ===")
    p = parse_proto(s)
    if p:
        for field, t, v in p:
            if t == 'bytes':
                preview = re.findall(rb'[ -~]{4,}', v[:80])
                print(f" field {field}: bytes[{len(v)}] ent={entropy(v):.2f} ascii={preview[:3]}")
                # recurse one level
                sub = parse_proto(v)
                if sub and len(sub) < 20:
                    for f2,t2,v2 in sub:
                        if t2=='bytes':
                            print(f"   .{f2}: bytes[{len(v2)}] ent={entropy(v2):.2f} ascii={re.findall(rb'[ -~]{4,}', v2[:120])[:3]}")
                        else:
                            print(f"   .{f2}: varint {v2}")
                # try decompress biggest fields
                for hdr, name in [(b'\x1f\x8b','gzip'),(b'\x78','zlib')]:
                    if v[:len(hdr)] == hdr:
                        try: print(f"   {name} decompress:", zlib.decompress(v, 47)[:100]); 
                        except Exception as e: print(f"   {name} fail: {e}")
            else:
                print(f" field {field}: varint {v}")
    else:
        print(" not valid protobuf at top level")
